using System.Collections.Immutable;
using System.Text;
using Microsoft.CodeAnalysis;

namespace FiveStar.Loader.Generators;

/// <summary>
/// The loader's shim registry at compile time. For every type with [Shim] methods, [ShimModule] attributes or
/// [NotImplementedTable] fields it writes a partial <c>RegisterShims(ShimTable)</c> that hands ShimTable each entry
/// point as a function pointer (<c>&amp;Method</c>), and <c>ShimTypes.Register</c> calls them all. No reflection runs,
/// so trimming and NativeAOT keep every shim, and a shim type has to be <c>partial</c>.
/// </summary>
[Generator(LanguageNames.CSharp)]
public sealed class ShimRegistryGenerator : IIncrementalGenerator
{
    private const string Namespace = "FiveStar.Loader.Shims";
    private const string Table = "global::" + Namespace + ".ShimTable";
    private const string Header = "// <auto-generated/>";

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        var methods = Find(context, "ShimAttribute", ShimStatements.Method);
        var modules = Find(context, "ShimModuleAttribute", ShimStatements.Modules);
        var tables = Find(context, "NotImplementedTableAttribute", ShimStatements.NotImplementedTable);
        var all = methods.Combine(modules).Combine(tables);

        context.RegisterSourceOutput(all, (production, found) => Emit(production, found.Left.Left.AddRange(found.Left.Right).AddRange(found.Right)));
    }

    private static IncrementalValueProvider<ImmutableArray<ShimRegistration>> Find(
        IncrementalGeneratorInitializationContext context,
        string attribute,
        Func<GeneratorAttributeSyntaxContext, ImmutableArray<ShimRegistration>> registrations)
    {
        return context.SyntaxProvider
            .ForAttributeWithMetadataName($"{Namespace}.{attribute}", static (_, _) => true, (target, _) => registrations(target))
            .SelectMany(static (found, _) => found)
            .Collect();
    }

    private static void Emit(SourceProductionContext production, ImmutableArray<ShimRegistration> registrations)
    {
        var types = registrations
            .GroupBy(registration => registration.Type)
            .OrderBy(group => group.Key.FullName, StringComparer.Ordinal)
            .ToList();

        foreach (var type in types)
        {
            var ordered = type
                .OrderBy(registration => registration.Kind)
                .ThenBy(registration => registration.Path, StringComparer.Ordinal)
                .ThenBy(registration => registration.Position);
            production.AddSource($"{type.Key.FullName.Replace("global::", string.Empty)}.Shims.g.cs", PartialType(type.Key, ordered));
        }

        production.AddSource("ShimTypes.g.cs", Index(types.Select(type => type.Key)));
    }

    /// <summary>The partial declaration with RegisterShims; it has the type's access to its private shim methods.</summary>
    private static string PartialType(ShimDeclaringType type, IEnumerable<ShimRegistration> registrations)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);

        if (type.Namespace is not null)
        {
            text.AppendLine($"namespace {type.Namespace};");
        }

        var modifiers = type.IsStatic ? "static unsafe partial" : "unsafe partial";
        text.AppendLine();
        text.AppendLine($"{modifiers} class {type.Name}");
        text.AppendLine("{");
        text.AppendLine($"    internal static void RegisterShims({Table} table)");
        text.AppendLine("    {");

        foreach (var registration in registrations)
        {
            text.AppendLine($"        {registration.Statement}");
        }

        text.AppendLine("    }");
        text.AppendLine("}");

        return text.ToString();
    }

    private static string Index(IEnumerable<ShimDeclaringType> types)
    {
        var text = new StringBuilder();
        text.AppendLine(Header);
        text.AppendLine($"namespace {Namespace};");

        text.AppendLine();
        text.AppendLine("/// <summary>Every type that declares shims, written by FiveStar.Loader.Generators.</summary>");
        text.AppendLine("internal static class ShimTypes");
        text.AppendLine("{");
        text.AppendLine($"    public static void Register({Table} table)");
        text.AppendLine("    {");

        foreach (var type in types)
        {
            text.AppendLine($"        {type.FullName}.RegisterShims(table);");
        }

        text.AppendLine("    }");
        text.AppendLine("}");

        return text.ToString();
    }
}
